1	/* Trap glue shared by all C-level round-trip fixtures.
2	 *
3	 * crt0.S calls init_mtvec() directly, BEFORE the .init_array walk, so
4	 * the trap vector is live before any C++ static constructor runs;
5	 * trap.S's m_trap_entry tail-calls handle_trap on every exception or
6	 * interrupt. vplat_syscalls.c routes syscalls through direct MMIO
7	 * (UART + SimControl/HTIF), not through `ecall`, so there's no
8	 * syscall-dispatch table here. Any trap is treated as a fatal error:
9	 * print a diagnostic and exit.
10	 */
11	
12	#ifdef __cplusplus
13	extern "C"
14	{
15	#endif
16	
17	#include <stdint.h>
18	#include <stdio.h>
19	
20	#include "ecall_hook.h"
21	#include "htif_client.h"
22	
23	#define WRITE_ERROR(format, ...) \
24	  fprintf(stderr, "\033[31m[ERROR] " format "\033[0m\n", ##__VA_ARGS__)
25	
26	#define CAUSE_ECALL_FROM_M_MODE 11UL
27	
28	__attribute__((used, noreturn)) void _exit(int exit_status);
29	
30	/* Raw, unbuffered emergency print: goes straight to the UART MMIO register,
31	 * bypassing stdio (fprintf/vfprintf can themselves be mid-fault, or the
32	 * app's libc state can be in a shape a trap handler shouldn't trust). */
33	static void raw_print_hex(const char* label, unsigned long v)
34	{
35	  for (const char* p = label; *p; ++p)
36	    htif_uart_putc(*p);
37	  htif_uart_putc('0');
38	  htif_uart_putc('x');
39	  char digits[2 * sizeof(unsigned long)];
40	  int n = 0;
41	  do {
42	    int nib = v & 0xf;
43	    digits[n++] = (char) (nib < 10 ? '0' + nib : 'a' + nib - 10);
44	    v >>= 4;
45	  } while (v);
46	  while (n > 0)
47	    htif_uart_putc(digits[--n]);
48	  htif_uart_putc('\r');
49	  htif_uart_putc('\n');
50	}
51	
52	void exception_handler(void* tf)
53	{
54	  /* XLEN-wide so rv64 mepc/mtval are not truncated and the format is warning-
55	   * free on both ABIs (unsigned long is 32-bit on ilp32, 64-bit on lp64). */
56	  unsigned long mcause, mdcause, mepc, mtval;
57	
58	  asm volatile("csrr %0, mcause" : "=r"(mcause));
59	  asm volatile("csrr %0, mdcause" : "=r"(mdcause));
60	  asm volatile("csrr %0, mepc" : "=r"(mepc));
61	  asm volatile("csrr %0, mtval" : "=r"(mtval));
62	
63	  raw_print_hex("mcause=", mcause);
64	  raw_print_hex("mepc=", mepc);
65	  raw_print_hex("mtval=", mtval);
66	
67	  const unsigned long intbit = 1UL << (__riscv_xlen - 1);  /* mcause MSB */
68	
69	  WRITE_ERROR("Trap occurred!");
70	  WRITE_ERROR("mcause: 0x%lx", mcause);
71	  WRITE_ERROR("mdcause: 0x%lx", mdcause);
72	  WRITE_ERROR("mepc: 0x%lx", mepc);
73	  WRITE_ERROR("mtval: 0x%lx", mtval);
74	  if (tf) {
75	    const unsigned long* regs = (const unsigned long*) tf;
76	    WRITE_ERROR("ra: 0x%lx", regs[1]);
77	    WRITE_ERROR("a0: 0x%lx", regs[10]);
78	  }
79	
80	  if ((mcause & intbit) == 0) {
81	    WRITE_ERROR("Exception code: %lu", mcause);
82	  } else {
83	    WRITE_ERROR("Interrupt occurred! Cause: %lu", mcause & ~intbit);
84	  }
85	
86	  /* _exit() (unlike exit()) does not flush stdio buffers; without this,
87	   * the diagnostic above is silently lost whenever stderr is
88	   * fully-buffered (e.g. not a tty under the vlinux syscall stdio path). */
89	  fflush(stderr);
90	
91	  _exit((int) mcause);
92	}
93	
94	__attribute__((weak)) int handle_ecall(unsigned long* regs)
95	{
96	  (void) regs;
97	  return 0;
98	}
99	
100	void handle_trap(unsigned long cause, void* tf)
101	{
102	  if (cause == CAUSE_ECALL_FROM_M_MODE && handle_ecall((unsigned long*) tf))
103	    return;
104	  exception_handler(tf);
105	}
106	
107	extern void m_trap_entry(void);
108	
109	/* Called by name from crt0.S (not via .init_array: the direct reference
110	 * is also what extracts this object from libandesim_runtime.a). */
111	void init_mtvec(void)
112	{
113	  uintptr_t handler_address = (uintptr_t) &m_trap_entry;
114	  asm volatile("csrw mtvec, %0" : : "r"(handler_address));
115	}
116	
117	#ifdef __cplusplus
118	}
119	#endif
